SELECT 'gongkao', '乘法原理', 'kp-pc-b-mul', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "乘法原理"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "分步相乘。完成一件事必须分几个连续的步骤，缺一不可。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“从A地到C地，必须先经过B地。A到B有3条路，B到C有4条路”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "N = m_1 \\times m_2 \\times \\dots \\times m_k"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[判断任务是否必须经过连续的步骤] --> B[确定每个步骤有多少种独立的方法]\nB --> C[将每一步的方法数相乘]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 穿衣服，有 3 件上衣，4 条裤子。搭配一套有几种穿法？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分步：必须先选上衣，再选裤子（缺一不可）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "计算：3 × 4 = 12 种。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "漏掉隐藏步骤：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "比如配车牌号，不仅有选数字，还有排列数字。每一个动作都是一个乘法环节。"}]}]}]}$$ AS jsonb), NULL, '乘法原理的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "乘法原理"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_b_mul", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
